import{_ as t,c as o,o as a,ag as s}from"./chunks/framework.DPDPlp3K.js";const g=JSON.parse('{"title":"Mole 安装脚本分析","description":"","frontmatter":{},"headers":[],"relativePath":"notion/mole-install-analysis.md","filePath":"notion/mole-install-analysis.md"}'),i={name:"notion/mole-install-analysis.md"};function l(d,e,c,n,r,h){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="mole-安装脚本分析" tabindex="-1">Mole 安装脚本分析 <a class="header-anchor" href="#mole-安装脚本分析" aria-label="Permalink to &quot;Mole 安装脚本分析&quot;">​</a></h1><blockquote><p>核查时间：2026 年 11 月 26 日 10:42（UTC+8）</p><p>说明：本文结论基于上述时间点从 GitHub 获取的 <code>tw93/mole/main/install.sh</code> 内容；脚本后续更新后，安装行为可能发生变化。</p></blockquote><p>默认这条命令<strong>不会编译主程序</strong>。它先下载最新正式版的<strong>源码包</strong>（主体是 shell 脚本），再单独下载两个 <strong>Go 预编译二进制</strong>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -fsSL</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> https://raw.githubusercontent.com/tw93/mole/main/install.sh</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> |</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> bash</span></span></code></pre></div><p>这条命令没有额外参数，走的是 stable 安装，不是 <code>main</code> 那种 edge 安装。</p><h2 id="它实际做了什么" tabindex="-1">它实际做了什么 <a class="header-anchor" href="#它实际做了什么" aria-label="Permalink to &quot;它实际做了什么&quot;">​</a></h2><ol><li><strong>拒绝 root。</strong> 用 <code>sudo</code> 跑会直接退出，提示不要用 sudo；写 <code>/usr/local/bin</code> 时脚本自己再要管理员权限。</li><li><strong>只支持 macOS 12 及以上。</strong></li><li><strong>如果当前 <code>mole</code> 已经是 Homebrew 装的</strong>（<code>Cellar/mole</code> 的符号链接），脚本会停下来，让你运行 <code>brew upgrade mole</code>，或者先 <code>brew uninstall --force mole</code> 再手动安装。</li><li><strong>拉源码，不编译主程序。</strong><ul><li>查最新 tag：<code>https://api.github.com/repos/tw93/mole/releases/latest</code>（形如 <code>V1.60.0</code>）</li><li>下载源码包：<code>https://github.com/tw93/mole/archive/refs/tags/&lt;tag&gt;.tar.gz</code></li><li>解压到临时目录。管道执行时没有本地仓库，所以一定走下载。</li></ul></li><li><strong>把文件拷到本机：</strong><ul><li><code>mole</code>、<code>mo</code> → <code>/usr/local/bin/</code>（目录不可写时使用 sudo）</li><li><code>bin/</code>、<code>lib/</code> → <code>~/.config/mole/</code></li><li>再修改已安装的 <code>mole</code>，把里面的 <code>SCRIPT_DIR</code> 指向 <code>~/.config/mole</code></li></ul></li><li><strong>再下载两个 Go 辅助程序</strong> <code>analyze</code> 和 <code>status</code>，校验 SHA256（有已登录的 <code>gh</code> 时还会验证 GitHub Actions 的构建证明），放到 <code>~/.config/mole/bin/</code>，文件名是 <code>analyze-go</code>、<code>status-go</code>。</li></ol><h2 id="可执行文件从哪来" tabindex="-1">可执行文件从哪来 <a class="header-anchor" href="#可执行文件从哪来" aria-label="Permalink to &quot;可执行文件从哪来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>来源</th><th>地址</th></tr></thead><tbody><tr><td><code>mole</code> / <code>mo</code></td><td>源码包里的 <strong>shell 脚本</strong>，直接拷贝</td><td><code>github.com/tw93/mole/archive/refs/tags/V&lt;版本&gt;.tar.gz</code></td></tr><tr><td><code>analyze</code>、<code>status</code></td><td><strong>Release 预编译二进制</strong>，按 CPU 选 <code>arm64</code> 或 <code>amd64</code></td><td><code>github.com/tw93/mole/releases/download/V&lt;版本&gt;/analyze-darwin-&lt;arch&gt;</code>，<code>status</code> 同理</td></tr><tr><td>校验文件</td><td>同一 Release</td><td><code>.../download/V&lt;版本&gt;/SHA256SUMS</code></td></tr></tbody></table><p>Apple Silicon 上就是 <code>analyze-darwin-arm64</code> 和 <code>status-darwin-arm64</code>。</p><h2 id="什么时候才会-go-build" tabindex="-1">什么时候才会 <code>go build</code> <a class="header-anchor" href="#什么时候才会-go-build" aria-label="Permalink to &quot;什么时候才会 `go build`&quot;">​</a></h2><p>源码编译只覆盖 <code>cmd/analyze</code> 和 <code>cmd/status</code>，而且要求本机已有 <code>go</code>。</p><ul><li><p><strong>默认安装不会编译。</strong> 二进制下载成功就使用 Release 文件。</p></li><li><p><strong>下载没完成</strong>（网络失败、这个 tag 还没发布二进制）时，才会尝试本地 <code>go build -ldflags=&quot;-s -w&quot;</code>。</p></li><li><p><strong>校验失败不会退回编译</strong>，直接中止，避免用未校验的构建顶替。</p></li><li><p>显式安装 edge 才会优先编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -fsSL</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> https://raw.githubusercontent.com/tw93/mole/main/install.sh</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> |</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> bash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -s</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> main</span></span></code></pre></div><p>这等价于设置 <code>MOLE_VERSION=main</code>、<code>MOLE_EDGE_INSTALL=true</code>。这种情况下源码来自 <code>main</code> 分支的 tarball 或 <code>git clone</code>，不是某个 Release tag。</p></li></ul>',13)]))}const m=t(i,[["render",l]]);export{g as __pageData,m as default};
